// Platform-independent kanadiff kana-size ncnn inference core.
// See kana_size_core.h — keep this file byte-identical with the PC copy in
// InstantJPDictPC/native/kana_size/.
//
// The converted graph reproduces the model author's ten published validation
// logits to 3.8e-06 on the host (fp32), and the param/bin are generated by a
// pipeline that writes the weight stream itself and asserts its byte total.
//
// Three conversion defects are worth knowing, because all three produce
// *plausible* output instead of an error, and all three bit this model:
//
//   * onnx2ncnn wrote an int64 initializer's 8 raw bytes while the param told
//     ncnn to read 4, so every later block in the sequential .bin was read
//     four bytes early. The symptom is a net whose outputs sit in a narrow
//     band, not scrambled garbage.
//   * `Convolution1D` is 2-D and takes its in-channel count from
//     `bottom_blob.h`, so a 3-D input that looks like 48 channels is silently
//     read as one.
//   * fp16 is a floor, not a detail: stock options cost ~1.5e-03 on this model
//     against an fp32 reference the artifact describes to 1e-06. The options
//     are pinned below, deliberately.
//
// Graph, as the param expresses it:
//
//   win  : 40 int32 byte values -> byte_emb (256x32)          -> [40,32]
//   pos  : MemoryData 0..39     -> pos_block (40x16)          -> [40,16]
//   cat  : concat -> [40,48] ; permute -> [48,40] channels-first
//   conv1: 48->64 k=5 pad=2 relu ; conv2: 64->64 k=3 pad=1 relu ; max over positions -> [64]
//   base : int32 pair index -> base_emb (20x16) -> [16] ; concat -> [80]
//   fc1  : 80->128 relu ; fc2: 128->1 -> logit          (sigmoid gives p(big))
//
// Positions are run one per extractor call. The param declares no batch
// dimension, and keeping one position per run leaves the int32 Embed inputs
// and the position-axis Reduction unambiguous.
#include "kana_size_core.h"

#include <cstdio>
#include <cstring>
#include <vector>

#include "ncnn/net.h"

namespace kana_size {

struct Model {
    ncnn::Net net;
};

Model* create(const char* param_path, const char* bin_path) {
    if (param_path == nullptr || bin_path == nullptr || *param_path == '\0' || *bin_path == '\0') {
        std::fprintf(stderr, "[kana_size] create: empty path\n");
        return nullptr;
    }

    auto* m = new Model();
    m->net.opt.use_fp16_packed = false;
    m->net.opt.use_fp16_storage = false;
    m->net.opt.use_fp16_arithmetic = false;
    m->net.opt.use_bf16_storage = false;
    m->net.opt.use_packing_layout = false;
    m->net.opt.num_threads = THREADS;

    if (m->net.load_param(param_path) != 0) {
        std::fprintf(stderr, "[kana_size] load_param failed: %s\n", param_path);
        delete m;
        return nullptr;
    }
    if (m->net.load_model(bin_path) != 0) {
        std::fprintf(stderr, "[kana_size] load_model failed: %s\n", bin_path);
        delete m;
        return nullptr;
    }
    std::fprintf(stderr, "[kana_size] model loaded (ncnn, fp32 pinned): %s\n", param_path);
    return m;
}

void destroy(Model* model) {
    delete model;
}

bool logits(Model* model, const int* win, const int* bases, int n, std::vector<float>& out) {
    out.clear();
    if (model == nullptr || win == nullptr || bases == nullptr || n <= 0) {
        return false;
    }

    // Copy the byte windows off the caller's buffer: ncnn::Mat wraps memory
    // without owning it, and the platform shells copy through their own
    // buffers too.
    std::vector<int> w((size_t) n * SEQ);
    std::memcpy(w.data(), win, sizeof(int) * (size_t) n * SEQ);

    out.assign((size_t) n, 0.0f);
    for (int i = 0; i < n; i++) {
        int base = bases[i];
        if (base < 0 || base >= PAIRS) base = 0;

        // Embed takes int indices, so both inputs are 4-byte elements, not floats.
        ncnn::Mat winMat(SEQ, w.data() + (size_t) i * SEQ, 4u);
        ncnn::Mat baseMat(1, &base, 4u);

        ncnn::Extractor ex = model->net.create_extractor();
        ex.input("win", winMat);
        ex.input("base", baseMat);
        ncnn::Mat logit;
        if (ex.extract("logit", logit) != 0 || logit.w < 1) {
            std::fprintf(stderr, "[kana_size] extract failed at position %d of %d\n", i, n);
            out.clear();
            return false;
        }
        out[(size_t) i] = logit[0];
    }
    return true;
}

} // namespace kana_size
